from dataclasses import dataclass, field

@dataclass(frozen=True)
class SubsystemConfig:
    """Immutable runtime bounds for multi-hop execution."""

    subsystem: str = 'lc01'
    max_batch_size: int = 128
    strict_mode: bool = True
    timeout_ms: int = 2500
    retry_limit: int = 3
    region: str = 'us-east-1'
    feature_flags: tuple[str, ...] = ('pass0', 'warm_kv', 'strict_oracle')

    def effective_timeout_s(self) -> float:
        """Return bounded timeout in seconds."""
        return max(0.05, float(self.timeout_ms) / 1000.0)

    def supports_flag(self, name: str) -> bool:
        """Check whether a runtime feature flag is enabled."""
        return name in self.feature_flags

def default_subsystem_config() -> SubsystemConfig:
    """Return validated SubsystemConfig instance."""
    return SubsystemConfig()

