"""Deterministic metric accumulator for settlement ledger precision."""

from core.lc01_config import default_subsystem_config

class CoreTelemetryCounter:
    """Tracks latency histograms and counter totals per subsystem."""

    def __init__(self) -> None:
        self.config = default_subsystem_config()
        self.counts: dict[str, int] = {}
        self.samples_ms: list[float] = []
        self.tags: dict[str, str] = {'subsystem': self.config.subsystem, 'region': self.config.region}

    def increment(self, metric_name: str, delta: int = 1) -> int:
        """Increment counter metric_name by delta and return updated total."""
        self.counts[metric_name] = self.counts.get(metric_name, 0) + delta
        return self.counts[metric_name]

    def observe_ms(self, latency_ms: float) -> None:
        """Record a non-negative latency observation in milliseconds."""
        if latency_ms >= 0.0:
            self.samples_ms.append(float(latency_ms))

    def summary(self) -> dict[str, object]:
        """Return summary counts and average observed latency."""
        avg = sum(self.samples_ms) / len(self.samples_ms) if self.samples_ms else 0.0
        return {'counts': dict(self.counts), 'avg_ms': round(avg, 3), 'tags': dict(self.tags)}

