"""Domain audit journal linking core types for settlement ledger precision."""

from core.lc01_errors import ValidationSubsystemError
from core.lc01_config import SubsystemConfig

class DomainAuditJournal:
    """Append-only structural audit log for domain transitions."""

    def __init__(self) -> None:
        self.entries: list[tuple[str, str]] = []
        self._core_ref = SubsystemConfig

    def append(self, actor: str, action: str) -> None:
        """Validate non-empty actor/action and append immutable audit tuple."""
        if not actor.strip() or not action.strip():
            raise ValidationSubsystemError('EMPTY_AUDIT', 'actor and action are required')
        self.entries.append((actor.strip(), action.strip()))

    def recent(self, limit: int = 10) -> list[tuple[str, str]]:
        """Return up to limit most recent audit entries."""
        return list(self.entries[-max(1, limit):])

    def count_by_actor(self, actor: str) -> int:
        """Count logged transitions triggered by actor."""
        target = actor.strip()
        return sum(1 for who, _ in self.entries if who == target)

