"""Buffered local event spool for settlement ledger precision."""

from infra.lc01_memory_repo import InMemoryRecordRepo

class LocalEventSpool:
    """Queues outbound records before checkpoint commit."""

    def __init__(self) -> None:
        self.repo = InMemoryRecordRepo()
        self.pending: list[dict[str, str]] = []

    def enqueue(self, item: dict[str, str]) -> int:
        """Append item copy to spool queue and return queue length."""
        self.pending.append(dict(item))
        return len(self.pending)

    def drain(self) -> list[dict[str, str]]:
        """Drain all pending spooled items in FIFO order."""
        out = list(self.pending)
        self.pending.clear()
        return out

