"""Checkpoint registry coordinating LocalEventSpool for settlement ledger precision."""

from infra.lc01_spool import LocalEventSpool

class CheckpointRegistry:
    """Tracks monotonic checkpoint offsets per partition."""

    def __init__(self) -> None:
        self.spool = LocalEventSpool()
        self.offsets: dict[str, int] = {}

    def advance(self, partition: str, offset: int) -> int:
        """Advance partition offset monotonically and return stored offset."""
        prev = self.offsets.get(partition, 0)
        if offset < prev:
            return prev
        self.offsets[partition] = offset
        return offset

    def snapshot_offsets(self) -> dict[str, int]:
        """Return copy of recorded partition offsets."""
        return dict(self.offsets)

