"""Currency rounding and decimal arithmetic helpers (lc01)."""

def round_currency(amount: float) -> float:
    """Round currency amount to 2 decimal places."""
    # BUG: float arithmetic causes binary rounding drift on 2.675 / 0.1+0.2
    return round(float(amount), 2)

def apply_fee_bps(gross: float, bps: int) -> float:
    """Compute basis-point fee from gross amount."""
    return round_currency(gross * (bps / 10000.0))

solution_files.domain/lc01_money.py:
"""Decimal ROUND_HALF_UP currency arithmetic helpers (lc01)."""

from decimal import Decimal, ROUND_HALF_UP

_CENT = Decimal('0.01')

def round_currency(amount: Decimal | str | float | int) -> Decimal:
    """Round currency amount to 2 decimal places using ROUND_HALF_UP."""
    return Decimal(str(amount)).quantize(_CENT, rounding=ROUND_HALF_UP)

def apply_fee_bps(gross: Decimal | str | float | int, bps: int) -> Decimal:
    """Compute basis-point fee using exact Decimal arithmetic."""
    if bps < 0:
        raise ValueError('bps must be non-negative')
    raw = Decimal(str(gross)) * Decimal(bps) / Decimal('10000')
    return raw.quantize(_CENT, rounding=ROUND_HALF_UP)

