"""Directed dependency graph helper with deterministic cycle detection (lc03)."""

def build_adjacency(edges: list[tuple[str, str]]) -> dict[str, set[str]]:
    """Build directed dependency map node -> prerequisites."""
    adj: dict[str, set[str]] = {}
    for node, dep in edges:
        adj.setdefault(node, set()).add(dep)
        adj.setdefault(dep, set())
    return adj

def find_cycle(adj: dict[str, set[str]]) -> list[str]:
    """Detect directed cycles including self-loops using 3-color DFS."""
    state: dict[str, int] = {}
    stack: list[str] = []

    def _dfs(node: str) -> list[str]:
        state[node] = 1
        stack.append(node)
        for nxt in sorted(adj.get(node, ())):
            nxt_state = state.get(nxt, 0)
            if nxt_state == 1:
                idx = stack.index(nxt)
                return stack[idx:] + [nxt]
            if nxt_state == 0:
                cyc = _dfs(nxt)
                if cyc:
                    return cyc
        stack.pop()
        state[node] = 2
        return []

    for node in sorted(adj):
        if state.get(node, 0) == 0:
            cyc = _dfs(node)
            if cyc:
                return cyc
    return []

