"""Deterministic lexicographic topological task scheduler (lc03)."""

import heapq
from core.lc03_graph import build_adjacency, find_cycle

def topological_order(nodes: list[str], edges: list[tuple[str, str]]) -> list[str]:
    """Return lexicographic topological_order or raise ValueError on find_cycle."""
    adj = build_adjacency(edges)
    for n in nodes:
        adj.setdefault(n, set())
    cyc = find_cycle(adj)
    if cyc:
        raise ValueError(f'Cycle detected: {cyc}')
    indeg = {n: len(deps) for n, deps in adj.items()}
    rev: dict[str, list[str]] = {n: [] for n in adj}
    for n, deps in adj.items():
        for d in deps:
            rev[d].append(n)
    heap = [n for n, deg in indeg.items() if deg == 0]
    heapq.heapify(heap)
    order: list[str] = []
    while heap:
        cur = heapq.heappop(heap)
        order.append(cur)
        for child in rev[cur]:
            indeg[child] -= 1
            if indeg[child] == 0:
                heapq.heappush(heap, child)
    return order

