class InflightRegistry:
    """Tracks inflight asyncio Futures keyed by cache key."""

    def __init__(self) -> None:
        self.pending: dict[str, asyncio.Future[object]] = {}

    def get_or_create(self, key: str) -> tuple[asyncio.Future[object], bool]:
        """Return (future, is_owner) coalescing concurrent callers on the same key."""
        existing = self.pending.get(key)
