"""Async single-flight coalescing cache with error cleanup (lc05)."""

import asyncio
from typing import Awaitable, Callable
from infra.lc05_inflight import InflightRegistry

class CoalescingCache:
    """Coalesce concurrent get_or_load calls via InflightRegistry and release on error."""

    def __init__(self) -> None:
        self._values: dict[str, object] = {}
        self._inflight = InflightRegistry()

    async def get_or_load(self, key: str, loader: Callable[[], Awaitable[object]]) -> object:
        """Return cached value or run one owner loader while waiters await future."""
        if key in self._values:
            return self._values[key]
        fut, owner = self._inflight.get_or_create(key)
        if not owner:
            return await asyncio.shield(fut)
        try:
            val = await loader()
        except BaseException as exc:
            if not fut.done():
                fut.set_exception(exc)
            self._inflight.release(key)
            raise
        self._values[key] = val
        if not fut.done():
            fut.set_result(val)
        self._inflight.release(key)
        return val

