solution_files.core/lc07_cursor.py:
"""HMAC-SHA256 pagination cursor codec with constant-time compare (lc07)."""

import base64
import hashlib
import hmac

def _sign(offset: int, secret: str) -> str:
    return hmac.new(secret.encode('utf-8'), str(offset).encode('utf-8'), hashlib.sha256).hexdigest()[:16]

def encode_signed_cursor(offset: int, secret: str) -> str:
    """Encode non-negative offset with HMAC signature into urlsafe base64 token."""
    if offset < 0:
        raise ValueError('offset must be non-negative')
    raw = f'{offset}:{_sign(offset, secret)}'.encode('utf-8')
    return base64.urlsafe_b64encode(raw).decode('ascii').rstrip('=')

def decode_signed_cursor(token: str, secret: str) -> int:
    """Restore base64 padding and verify HMAC signature using hmac.compare_digest."""
    padded = token + '=' * (-len(token) % 4)
    try:
        decoded = base64.urlsafe_b64decode(padded.encode('ascii')).decode('utf-8')
        off_str, sig = decoded.split(':', 1)
        offset = int(off_str)
    except Exception as exc:
        raise ValueError('Malformed cursor token') from exc
    expected = _sign(offset, secret)
    if offset < 0 or not hmac.compare_digest(sig, expected):
        raise ValueError('Invalid cursor signature')
    return offset

