"""Core RBAC evaluator with transitive role inheritance and explicit deny precedence (lc08)."""

from fnmatch import fnmatch

def expand_roles(roles: list[str], role_parents: dict[str, list[str]]) -> set[str]:
    """Collect transitive closure of roles via role_parents."""
    seen: set[str] = set()
    stack = list(roles)
    while stack:
        cur = stack.pop()
        if cur in seen:
            continue
        seen.add(cur)
        stack.extend(role_parents.get(cur, ()))
    return seen

def evaluate_rbac(roles: list[str], role_parents: dict[str, list[str]], rules: list[tuple[str, str, str]], action: str) -> bool:
    """Evaluate rules with wildcard fnmatch and explicit deny precedence over allow."""
    effective = expand_roles(roles, role_parents)
    allowed = False
    for role, effect, pattern in rules:
        if role not in effective or not fnmatch(action, pattern):
            continue
        if effect == 'deny':
            return False
        if effect == 'allow':
            allowed = True
    return allowed

