"""Idempotent order creation service enforcing digest conflict & TTL (lc09)."""

from typing import Callable
from core.lc09_errors import ConflictSubsystemError
from core.lc09_idempotency import payload_digest

class IdempotentOrderService:
    """Deduplicate submit calls by idempotency key with conflict detection and TTL expiry."""

    def __init__(self, ttl_s: float, clock: Callable[[], float]) -> None:
        self.ttl_s = float(ttl_s)
        self._clock = clock
        self._records: dict[str, tuple[str, dict[str, object], float]] = {}
        self._seq = 0

    def submit(self, key: str, payload: dict[str, object]) -> dict[str, object]:
        """Return cached order on matching digest within TTL, raise ConflictSubsystemError on mismatch."""
        now = float(self._clock())
        digest = payload_digest(payload)
        existing = self._records.get(key)
        if existing is not None:
            old_digest, cached_resp, expires_at = existing
            if now < expires_at:
                if old_digest != digest:
                    raise ConflictSubsystemError('IDEM_CONFLICT', f'Payload mismatch for {key}')
                return dict(cached_resp)
        self._seq += 1
        resp = {'order_id': f'ORD-{self._seq}', 'amount': payload.get('amount')}
        self._records[key] = (digest, resp, now + self.ttl_s)
        return dict(resp)

