"""Semantic version parser with numeric prerelease identifiers (lc12)."""

import re

_RE = re.compile(r'^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?$')

def semver_key(raw: str) -> tuple[int, int, int, int, tuple[tuple[int, object], ...]]:
    m = _RE.match(raw.strip())
    if not m:
        raise ValueError(raw)
    # BUG: puts prerelease above final release
    return (int(m.group(1)), int(m.group(2)), int(m.group(3)), 1 if m.group(4) else 0, ())

