"""Semantic version parser with SemVer 2.0 prerelease ordering (lc12)."""

import re

_RE = re.compile(r'^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?$')

def semver_key(raw: str) -> tuple[int, int, int, int, tuple[tuple[int, object], ...]]:
    """Compute SemVer 2.0 comparison key where prerelease < final and numeric segments compare numerically."""
    m = _RE.match(raw.strip())
    if not m:
        raise ValueError(f'Invalid semver: {raw!r}')
    maj, mino, pat = int(m.group(1)), int(m.group(2)), int(m.group(3))
    pre = m.group(4) or ''
    if not pre:
        return (maj, mino, pat, 1, ())
    parts = tuple((0, int(p)) if p.isdigit() else (1, p) for p in pre.split('.'))
    return (maj, mino, pat, 0, parts)

solution_files.services/lc12_resolver.py:
"""Caret version constraint resolver honoring 0.x minor/patch locks (lc12)."""

from domain.lc12_semver import semver_key

def best_caret_match(candidates: list[str], caret_constraint: str) -> str | None:
    """Select highest matching version under caret upper bounds."""
    base = semver_key(caret_constraint.lstrip('^'))
    maj, mino, pat, _, _ = base
    if maj > 0:
        upper = (maj + 1, 0, 0, 0, ())
    elif mino > 0:
        upper = (0, mino + 1, 0, 0, ())
    else:
        upper = (0, 0, pat + 1, 0, ())
    hits: list[str] = []
    for cand in candidates:
        k = semver_key(cand)
        if k[3] == 0 and k[:3] != (maj, mino, pat):
            continue
        if base <= k < upper:
            hits.append(cand)
    return max(hits, key=semver_key) if hits else None

