"""Cron field parser supporting *, ranges, lists, and /step intervals (lc13)."""

def expand_cron_field(expr: str, min_val: int, max_val: int) -> set[int]:
    """Expand cron field expression into valid integer set within [min_val, max_val]."""
    out: set[int] = set()
    for raw_part in expr.split(','):
        part = raw_part.strip()
        if '/' in part:
            base_str, step_str = part.split('/', 1)
            step = int(step_str)
            if step <= 0:
                raise ValueError('step must be positive')
        else:
            base_str, step = part, 1
        if base_str == '*':
            lo, hi = min_val, max_val
        elif '-' in base_str:
            lo_s, hi_s = base_str.split('-', 1)
            lo, hi = int(lo_s), int(hi_s)
        else:
            lo = hi = int(base_str)
            if '/' in part:
                hi = max_val
        if lo < min_val or hi > max_val or lo > hi:
            raise ValueError(f'Out of range cron field: {part!r}')
        out.update(range(lo, hi + 1, step))
    return out

