"""Cron field parser missing */step modulo offset (lc13)."""

def expand_cron_field(expr: str, min_val: int, max_val: int) -> set[int]:
    out: set[int] = set()
    for part in expr.split(','):
        part = part.strip()
        if part == '*':
            out.update(range(min_val, max_val + 1))
        elif '-' in part:
            lo, hi = (int(x) for x in part.split('-', 1))
            out.update(range(lo, hi + 1))
        elif part.isdigit():
            out.add(int(part))
    # BASELINE OMISSION: ignores '/step' expressions like '*/15' or '2-10/2'
    return out

