solution_files.services/lc14_compactor.py:
"""WAL tombstone compactor applying last-write-wins and delete tombstones (lc14)."""

from infra.lc14_wal import decode_wal_frame

def compact_wal_lines(lines: list[str]) -> dict[str, object]:
    """Replay verified WAL frames and purge deleted tombstone keys."""
    state: dict[str, object] = {}
    for ln in lines:
        if not ln.strip():
            continue
        frame = decode_wal_frame(ln)
        key = str(frame['key'])
        if frame['op'] == 'del':
            state.pop(key, None)
        elif frame['op'] == 'put':
            state[key] = frame.get('value')
        else:
            raise ValueError(f"Unknown WAL op: {frame['op']!r}")
    return state

