class ServiceHealthDispatcher:
    """Coordinates health checks across service and domain components."""

    def __init__(self) -> None:
        self.telemetry = CoreTelemetryCounter()
        self.domain_symbol = DomainAuditJournal
        self.registered_components: list[str] = []

    def register(self, component: str) -> None:
        """Register a named subsystem component for health polling."""
        cleaned = component.strip()
        if cleaned and cleaned not in self.registered_components:
            self.registered_components.append(cleaned)

