class CliCommandAdapter:
    """Formats deterministic CLI diagnostics from HttpBoundaryAdapter."""

    def __init__(self) -> None:
        self.http_adapter = HttpBoundaryAdapter()

    def format_status(self, request_id: str) -> str:
        """Format single-line health probe summary string."""
        info = self.http_adapter.handle_health(request_id)
        return f"[{info['component']}] req={info['request_id']} seq={info['sequence']}"

    def parse_kv_flags(self, argv: list[str]) -> dict[str, str]:
        """Parse --key=value CLI overrides into a clean dictionary."""
        parsed: dict[str, str] = {}
        for tok in argv:
            if tok.startswith('--') and '=' in tok:
                k, v = tok[2:].split('=', 1)
                parsed[k.strip()] = v.strip()
        return parsed

