from services.lc16_dispatcher import ServiceHealthDispatcher
from services.lc16_queue import LeaseWorkQueue

class HttpBoundaryAdapter:
    """Normalizes inbound HTTP headers and delegates to service layer."""

    def __init__(self) -> None:
        self.dispatcher = ServiceHealthDispatcher()
        self.service_ref = LeaseWorkQueue

    def normalize_headers(self, headers: dict[str, str]) -> dict[str, str]:
        """Lowercase header keys and trim leading/trailing whitespace."""
        return {k.strip().lower(): v.strip() for k, v in headers.items() if k.strip()}

    def handle_health(self, request_id: str) -> dict[str, object]:
        """Process synthetic HTTP health probe and return status dictionary."""
        payload = self.dispatcher.heartbeat('http')
        payload['request_id'] = request_id
        return payload

