files.infra/lc16_memory_repo.py:
"""In-memory infrastructure repository for priority lease queue."""

from adapters.lc16_webhook_adapter import WebhookEnvelopeAdapter
from core.lc16_errors import ConflictSubsystemError

class InMemoryRecordRepo:
    """Stores versioned key-value records with optimistic revision check."""

    def __init__(self) -> None:
        self._rows: dict[str, tuple[int, dict[str, str]]] = {}
        self._webhook = WebhookEnvelopeAdapter()

    def put(self, key: str, expected_rev: int, value: dict[str, str]) -> int:
        """Store value if current revision matches expected_rev, else raise ConflictSubsystemError."""
        cur_rev, _ = self._rows.get(key, (0, {}))
        if cur_rev != expected_rev:
            raise ConflictSubsystemError('REV_MISMATCH', f'Expected {expected_rev}, got {cur_rev}')
        new_rev = cur_rev + 1
        self._rows[key] = (new_rev, dict(value))
        return new_rev

    def get(self, key: str) -> dict[str, str] | None:
        """Retrieve stored record copy for key or None if absent."""
        row = self._rows.get(key)
        return dict(row[1]) if row is not None else None

    def keys(self) -> list[str]:
        """Return sorted stored keys."""
        return sorted(self._rows)

files.infra/lc16_spool.py:
"""Buffered local event spool for priority lease queue."""

from infra.lc16_memory_repo import InMemoryRecordRepo

class LocalEventSpool:
    """Queues outbound records before checkpoint commit."""

    def __init__(self) -> None:
        self.repo = InMemoryRecordRepo()
        self.pending: list[dict[str, str]] = []

    def enqueue(self, item: dict[str, str]) -> int:
        """Append item copy to spool queue and return queue length."""
        self.pending.append(dict(item))
        return len(self.pending)

    def drain(self) -> list[dict[str, str]]:
        """Drain all pending spooled items in FIFO order."""
        out = list(self.pending)
        self.pending.clear()
        return out

