"""Runtime configuration and envelope defaults for consistent hash ring."""

from dataclasses import dataclass, field

@dataclass(frozen=True)
class SubsystemConfig:
    """Immutable runtime bounds for multi-hop execution."""

    subsystem: str = 'lc17'
    max_batch_size: int = 128
    strict_mode: bool = True
    timeout_ms: int = 2500
    retry_limit: int = 3
    region: str = 'us-east-1'
    feature_flags: tuple[str, ...] = ('pass0', 'warm_kv', 'strict_oracle')

    def effective_timeout_s(self) -> float:
        """Return bounded timeout in seconds."""
        return max(0.05, float(self.timeout_ms) / 1000.0)

    def supports_flag(self, name: str) -> bool:
        """Check whether a runtime feature flag is enabled."""
        return name in self.feature_flags

def default_subsystem_config() -> SubsystemConfig:
    """Return validated SubsystemConfig instance."""
    return SubsystemConfig()

files.core/lc17_errors.py:
"""Typed error hierarchy for consistent hash ring."""

class SubsystemError(RuntimeError):
    """Base error raised by core and domain operations."""

    def __init__(self, code: str, message: str, *, retryable: bool = False) -> None:
        super().__init__(message)
        self.code = code
        self.message = message
        self.retryable = retryable

    def to_dict(self) -> dict[str, object]:
        """Serialize error metadata for structured telemetry logs."""
        return {'code': self.code, 'message': self.message, 'retryable': self.retryable}

class ValidationSubsystemError(SubsystemError):
    """Raised when domain invariants reject an operation."""

class ConflictSubsystemError(SubsystemError):
    """Raised on state conflict or stale sequence mismatch."""

class BoundarySubsystemError(SubsystemError):
    """Raised when adapter boundary validation rejects payload fields."""

