from domain.lc17_ring import hash_token

class HashRingRouter:
    """Route keys onto virtual node ring using bisect_left with wrap-around."""

    def __init__(self, nodes: list[str], vnodes: int = 16) -> None:
        if not nodes or vnodes <= 0:
            raise ValueError('nodes and vnodes must be non-empty/positive')
        self.ring: list[tuple[int, str]] = []
        for node in sorted(set(nodes)):
            for vn in range(vnodes):
                self.ring.append((hash_token(f'{node}#{vn}'), node))
        self.ring.sort(key=lambda item: item[0])
        self._positions = [pos for pos, _ in self.ring]

    def route_key(self, key: str) -> str:
        """Select owning physical node for key via bisect_left wrap-around."""
        target = hash_token(key)
        idx = bisect_left(self._positions, target)
        if idx >= len(self.ring):
            idx = 0
        return self.ring[idx][1]

