"""Pairwise SHA-256 Merkle tree root and level builder (lc18)."""

import hashlib

def _h(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def build_merkle_levels(chunks: list[bytes]) -> list[list[str]]:
    """Build bottom-up Merkle tree levels with odd-leaf duplication."""
    if not chunks:
        return [[_h(b'')]]
    level = [_h(c) for c in chunks]
    levels = [level]
    while len(level) > 1:
        padded = list(level) if len(level) % 2 == 0 else list(level) + [level[-1]]
        level = [
            _h((padded[i] + padded[i + 1]).encode('ascii'))
            for i in range(0, len(padded), 2)
        ]
        levels.append(level)
    return levels

def merkle_root(chunks: list[bytes]) -> str:
    """Return top-level Merkle root hex digest."""
    return build_merkle_levels(chunks)[-1][0]

