"""Two-phase saga coordinator executing strict reverse LIFO rollback (lc19)."""

from domain.lc19_saga import SagaOutcome, SagaStep

def run_saga(steps: list[SagaStep]) -> SagaOutcome:
    """Run steps and execute compensate in reverse LIFO order on failure, recording compensation_errors."""
    completed: list[SagaStep] = []
    try:
        for step in steps:
            step.execute()
            completed.append(step)
    except Exception:
        compensated: list[str] = []
        errors: list[str] = []
        for done in reversed(completed):
            try:
                done.compensate()
                compensated.append(done.name)
            except Exception:
                errors.append(done.name)
        return SagaOutcome(False, compensated, errors)
    return SagaOutcome(True, [], [])

