class SubsystemError(RuntimeError):
    """Base error raised by core and domain operations."""

    def __init__(self, code: str, message: str, *, retryable: bool = False) -> None:
        super().__init__(message)
        self.code = code
        self.message = message
        self.retryable = retryable

    def to_dict(self) -> dict[str, object]:
        """Serialize error metadata for structured telemetry logs."""
        return {'code': self.code, 'message': self.message, 'retryable': self.retryable}

class ValidationSubsystemError(SubsystemError):
    """Raised when domain invariants reject an operation."""

class ConflictSubsystemError(SubsystemError):
    """Raised on state conflict or stale sequence mismatch."""

class BoundarySubsystemError(SubsystemError):
    """Raised when adapter boundary validation rejects payload fields."""

