from pathlib import Path

_ROOT = Path(__file__).resolve().parents[1]
if str(_ROOT) not in sys.path:
    sys.path.insert(0, str(_ROOT))

from adapters.lc20_env_loader import render_masked_config
from core.lc20_merge import deep_merge_config

def test_deep_merge_non_mutating_and_masked() -> None:
    base = {'db': {'host': 'localhost', 'port': 5432}, 'auth': {'api_token': 'demo-t1'}}
    ovr = {'db': {'port': 6432}, 'auth': {'region': 'eu'}}
    merged = deep_merge_config(base, ovr)
    assert merged['db'] == {'host': 'localhost', 'port': 6432}
    assert base['db']['port'] == 5432
    masked = render_masked_config(base, ovr)
    assert masked['auth'] == {'api_token': '[REDACTED]', 'region': 'eu'}

