"""Non-mutating hierarchical config deep_merge_config helper (lc20)."""

from copy import deepcopy

def deep_merge_config(base: dict[str, object], override: dict[str, object]) -> dict[str, object]:
    """Deep-merge override into base without mutating either input mapping."""
    out: dict[str, object] = deepcopy(base)
    for key, val in override.items():
        cur = out.get(key)
        if isinstance(cur, dict) and isinstance(val, dict):
            out[key] = deep_merge_config(cur, val)
        else:
            out[key] = deepcopy(val)
    return out

