"""Config masking adapter protecting sensitive fields in diffs (lc20)."""

from core.lc20_merge import deep_merge_config

_MASKED_KEYS = frozenset({'api_token', 'password', 'signing_key', 'auth_header'})

def _mask_tree(node: dict[str, object]) -> dict[str, object]:
    out: dict[str, object] = {}
    for k, v in node.items():
        if k.lower() in _MASKED_KEYS:
            out[k] = '[REDACTED]'
        elif isinstance(v, dict):
            out[k] = _mask_tree(v)
        else:
            out[k] = v
    return out

def render_masked_config(base: dict[str, object], override: dict[str, object]) -> dict[str, object]:
    """Merge base and override via deep_merge_config and redact sensitive keys."""
    return _mask_tree(deep_merge_config(base, override))

